### Implementation
Create `packages/shadmin/src/cli/vite-plugin.ts`:
- `shadminPlugin(options): Plugin`

### Plugin Structure
```typescript
export function shadminPlugin(options: ShadminPluginOptions): Plugin {
  const virtualModuleId = 'virtual:shadmin-entry'

  return {
    name: 'shadmin',
    resolveId(id) {
      if (id === virtualModuleId) return id
    },
    async load(id) {
      if (id === virtualModuleId) {
        const resources = await scanResources(options.root)
        return generateEntry({ resources, ...options })
      }
    },
    handleHotUpdate({ file, server }) {
      if (isResourceFile(file) || isConfigFile(file)) {
        // Invalidate virtual module
        const mod = server.moduleGraph.getModuleById(virtualModuleId)
        if (mod) server.moduleGraph.invalidateModule(mod)
        server.ws.send({ type: 'full-reload' })
      }
    }
  }
}
```

