```typescript
#!/usr/bin/env node
import { cac } from 'cac'
import { createServer, build, preview } from './server'

const cli = cac('shadmin')

cli
  .command('[root]', 'Start dev server')
  .alias('dev')
  .option('--port <port>', 'Port to listen on', { default: 5173 })
  .option('--host [host]', 'Expose to network')
  .option('--open', 'Open browser')
  .action(async (root, options) => {
    await createServer({ root: root || process.cwd(), ...options })
  })

cli
  .command('build [root]', 'Build for production')
  .action(async (root) => {
    await build({ root: root || process.cwd() })
  })

cli
  .command('preview [root]', 'Preview production build')
  .option('--port <port>', 'Port', { default: 4173 })
  .action(async (root, options) => {
    await preview({ root: root || process.cwd(), ...options })
  })

cli.help()
cli.version(require('../package.json').version)
cli.parse()
```

